/** Coordinate unchanged original extraction and AMPS assessment from complete RMA inputs. */
public final class HopsAssessmentWorkflowCli {
    private HopsAssessmentWorkflowCli() { }
    private static final String STATUS="complete-original-hops-rma-assessment-workflow-only";
    private static final String ACTION="Required action: retain the complete workflow directory, every original input/output and both stages' diagnostics. Use permitted native Linux x86_64 application JDK21, the exact full MaltExtract1.7/Java8 provider, complete matching ncbi.map/ncbi.tre resources, complete classified RMA6 inputs and the pinned public R4.0.5 postprocessing provider. If a required install/runtime/execution is unavailable or forbidden, skip dependent assessment. Resolve the named issue before retrying a NEW directory. Read WARNINGS.md. Select complete-def-anc explicitly: this disables original sampling, destacking and duplicate removal and changes the method. No MALT alignment/index creation, historical2017 database reconstruction, author-setting recovery or automatic biological authentication is claimed. Empty/insufficient evidence and failed original plots never establish absence.";
    private static final Set<String> EXTRACT=Set.of("--resources","--targets","--rma-list","--profile","--input-provenance","--maximum-file-bytes","--maximum-input-bytes","--maximum-reads","--maximum-matches","--maximum-samples","--maximum-selected","--maximum-map-rows","--maximum-map-characters","--maximum-tree-nodes","--wall-seconds","--heap-mib","--threads","--gc-threads");
    private static final Set<String> POST=Set.of("--maximum-file-bytes","--maximum-samples","--threads","--maximum-table-rows","--maximum-table-cells","--maximum-taxa","--maximum-bundle-bytes","--maximum-files","--wall-seconds");
    private static final int FILES=500000;
    private static final long FILE_BYTES=10000000000L,TOTAL_BYTES=1000000000000L;
    private static final class Skipped extends IOException {private static final long serialVersionUID=1L;Skipped(String message){super(message);}}
    public static void main(String[] args){int code=run(args,System.out,System.err);if(code!=0)System.exit(code);}
    static int run(String[] args,PrintStream stdout,PrintStream stderr) {
        Path out=null;boolean owned=false;String stage="input validation";
        try {
            if(args.length==1&&args[0].equals("--help")){stdout.println(help());return 0;}
            var o=options(args);out=path(required(o,"--out"));
            if(Files.exists(out,LinkOption.NOFOLLOW_LINKS))throw new IOException("Output must be NEW; prior attempts remain unchanged");NextflowFiles.directory(out.getParent());
            Path postRuntime=path(required(o,"--post-runtime"));
            if(o.containsKey("--verify")) {
                if(!o.keySet().equals(Set.of("--verify","--reader-runtime","--post-runtime","--out")))throw new IOException("Saved workflow verification accepts only its complete root, providers and NEW output");
                Path root=path(o.get("--verify")),reader=path(required(o,"--reader-runtime"));disjoint(out,List.of(root,reader,postRuntime));Files.createDirectory(out);owned=true;stage="saved workflow verification";verify(root,reader,postRuntime,out);
                stdout.println("PASS COMPLETE SAVED HOPS RMA ASSESSMENT; source scientific fields/RData rechecked; no fitting/plotting repeated");return 0;
            }
            if(o.containsKey("--reader-runtime"))throw new IOException("Fitting uses --maltextract-runtime; --reader-runtime belongs to saved verification");
            if(!required(o,"--profile").equals("complete-def-anc"))throw new IOException("This declared workflow requires explicit complete-def-anc; no filter/method fallback");
            if(!Set.of("true","false").contains(required(o,"--emit-json")))throw new IOException("Explicit --emit-json true|false required");
            if(System.getProperty("os.name").equals("Linux"))HopsPostprocessingCli.requireOriginalPlotPrefix(out.toString());
            Path maltRuntime=path(required(o,"--maltextract-runtime")),resources=path(required(o,"--resources")),targets=path(required(o,"--targets")),rma=path(required(o,"--rma-list"));required(o,"--input-provenance");disjoint(out,List.of(maltRuntime,postRuntime,resources,targets,rma));
            Files.createDirectory(out);owned=true;NextflowFiles.writeJson(out.resolve("workflow-invocation.json"),Map.of("schema","HOPS_RMA_ASSESSMENT_INVOCATION_V1","producer_root",out.toString(),"working_directory",Path.of("").toAbsolutePath().normalize().toString(),"options",o,"mode","me_po_complete_declared_profile"));
            var extract=new ArrayList<String>(List.of("--runtime",maltRuntime.toString(),"--out",out.resolve("extraction").toString()));
            for(var e:o.entrySet())if(EXTRACT.contains(e.getKey()))extract.addAll(List.of(e.getKey(),e.getValue()));
            stage="original MaltExtract extraction";int code=extract(extract,out.resolve("extraction-stage.stdout"),out.resolve("extraction-stage.stderr"));requireStage(code,stage,out.resolve("extraction-stage.stderr"));
            var post=new ArrayList<String>(List.of("--maltextract-bundle",out.resolve("extraction/bundle").toString(),"--reader-runtime",maltRuntime.toString(),"--post-runtime",postRuntime.toString(),"--filter","def_anc","--emit-json",o.get("--emit-json"),"--out",out.resolve("assessment").toString()));
            for(var e:o.entrySet())if(POST.contains(e.getKey()))post.addAll(List.of(e.getKey(),e.getValue()));
            stage="original HOPS postprocessing";code=post(post,out.resolve("assessment-stage.stdout"),out.resolve("assessment-stage.stderr"));requireStage(code,stage,out.resolve("assessment-stage.stderr"));
            same(inventory(out.resolve("extraction/bundle"),null),inventory(out.resolve("assessment/bundle/extraction"),null),"Assessment did not consume the complete identical extraction bundle");
            var extraction=NextflowFiles.object(NextflowFiles.json(out.resolve("extraction/bundle/audit.json"),67108864));var assessment=NextflowFiles.object(NextflowFiles.json(out.resolve("assessment/bundle/audit.json"),67108864));
            var report=new TreeMap<String,Object>();report.put("status",STATUS);report.put("mode","me_po_complete_declared_profile");report.put("producer_root",out.toString());report.put("extraction_profile","complete-def-anc");report.put("input_provenance",extraction.get("input_provenance"));report.put("sample_labels",extraction.get("sample_labels"));report.put("selection",extraction.get("selection"));report.put("scientific_assessment",assessment.get("scientific_audit"));report.put("new_tool_credit",0);report.put("whole_hops_qualified",false);report.put("biological_result_admitted",false);report.put("producer_authenticated",false);NextflowFiles.writeJson(out.resolve("workflow-audit.json"),report);
            Files.writeString(out.resolve("WARNINGS.md"),warnings(),StandardCharsets.UTF_8,StandardOpenOption.CREATE_NEW);
            NextflowFiles.writeJson(out.resolve("COMPONENT_COMPLETED.json"),Map.of("status",STATUS,"files",inventory(out,"COMPONENT_COMPLETED.json"),"new_tool_credit",0));
            NextflowFiles.json(out.resolve("COMPONENT_COMPLETED.json"),67108864);
            bindInvocation(NextflowFiles.object(NextflowFiles.json(out.resolve("workflow-invocation.json"),16777216)),report,extraction,assessment,out.resolve("extraction/bundle"));
            stdout.println("COMPLETE ORIGINAL HOPS RMA ASSESSMENT: "+out+"; inspect both stages' original outputs, WARNINGS.md and assessment plots. Whole HOPS/catalog admission remains separate.");return 0;
        }catch(Exception failure) {
            int code=failure instanceof Skipped?3:2;String status=code==3?"SKIP3 DEPENDENT ASSESSMENT SKIPPED":"FAIL2 NO RESULT ADMITTED";
            stderr.println("HOPS ASSESSMENT WORKFLOW "+status+" at "+stage+": "+failure+"\n"+ACTION);
            if(owned&&out!=null)try{NextflowFiles.writeJson(out.resolve("FAILURE.json"),Map.of("status",status,"stage",stage,"cause",failure.toString(),"required_action",ACTION));Files.writeString(out.resolve("WARNINGS_FAILURE.md"),"# "+status+"\n\nStage: "+stage+"\n\n"+failure+"\n\n"+ACTION+"\n",StandardCharsets.UTF_8,StandardOpenOption.CREATE_NEW);}catch(IOException diagnostic){stderr.println("Retain failed workflow; diagnostic write failed: "+diagnostic);}
            return code;
        }
    }
    private static void verify(Path root,Path reader,Path postRuntime,Path out)throws IOException {
        NextflowFiles.directory(root);if(Files.exists(root.resolve("FAILURE.json"))||Files.exists(root.resolve("WARNINGS_FAILURE.md")))throw new IOException("Failed/provisional workflow cannot be admitted");
        var complete=NextflowFiles.object(NextflowFiles.json(root.resolve("COMPONENT_COMPLETED.json"),67108864));NextflowFiles.keys(complete,"status","files","new_tool_credit");
        if(!STATUS.equals(complete.get("status"))||NextflowFiles.integer(complete.get("new_tool_credit"),0,0)!=0)throw new IOException("Unsupported workflow completion scope");
        var expected=pins(complete.get("files"));same(expected,inventory(root,"COMPONENT_COMPLETED.json"),"Complete workflow inventory differs");
        if(!expected.containsKey("extraction/bundle/COMPONENT_COMPLETED.json")||!expected.containsKey("assessment/bundle/COMPONENT_COMPLETED.json")||!expected.containsKey("assessment/bundle/extraction/COMPONENT_COMPLETED.json"))throw new IOException("Complete nested stage markers are missing");
        var report=NextflowFiles.object(NextflowFiles.json(root.resolve("workflow-audit.json"),67108864));NextflowFiles.keys(report,"status","mode","producer_root","extraction_profile","input_provenance","sample_labels","selection","scientific_assessment","new_tool_credit","whole_hops_qualified","biological_result_admitted","producer_authenticated");
        if(!STATUS.equals(report.get("status"))||!"me_po_complete_declared_profile".equals(report.get("mode"))||!"complete-def-anc".equals(report.get("extraction_profile"))||NextflowFiles.integer(report.get("new_tool_credit"),0,0)!=0||!Boolean.FALSE.equals(report.get("whole_hops_qualified"))||!Boolean.FALSE.equals(report.get("biological_result_admitted"))||!Boolean.FALSE.equals(report.get("producer_authenticated")))throw new IOException("Contradictory workflow scope/profile/biology claim");
        int code=extract(List.of("--verify",root.resolve("extraction/bundle").toString(),"--runtime",reader.toString()),out.resolve("extraction-verify.stdout"),out.resolve("extraction-verify.stderr"));requireStage(code,"saved extraction",out.resolve("extraction-verify.stderr"));
        same(inventory(root.resolve("extraction/bundle"),null),inventory(root.resolve("assessment/bundle/extraction"),null),"Assessment and extraction stages have different complete inputs");
        code=post(List.of("--verify",root.resolve("assessment/bundle").toString(),"--reader-runtime",reader.toString(),"--post-runtime",postRuntime.toString(),"--out",out.resolve("assessment-verification").toString()),out.resolve("assessment-verify.stdout"),out.resolve("assessment-verify.stderr"));requireStage(code,"saved assessment",out.resolve("assessment-verify.stderr"));
        var extraction=NextflowFiles.object(NextflowFiles.json(root.resolve("extraction/bundle/audit.json"),67108864));var assessment=NextflowFiles.object(NextflowFiles.json(root.resolve("assessment/bundle/audit.json"),67108864));
        same("complete-def-anc",extraction.get("profile"),"Extraction profile differs from workflow choice");
        for(String key:List.of("input_provenance","sample_labels","selection"))same(extraction.get(key),report.get(key),"Workflow extraction summary differs: "+key);
        same(assessment.get("scientific_audit"),report.get("scientific_assessment"),"Workflow scientific assessment differs");
        var invocation=NextflowFiles.object(NextflowFiles.json(root.resolve("workflow-invocation.json"),16777216));bindInvocation(invocation,report,extraction,assessment,root.resolve("extraction/bundle"));
        if(!Files.readString(root.resolve("WARNINGS.md"),StandardCharsets.UTF_8).equals(warnings()))throw new IOException("Workflow interpretation/recovery warnings differ");same(expected,inventory(root,"COMPONENT_COMPLETED.json"),"Read-only workflow verification changed inputs");
        NextflowFiles.writeJson(out.resolve("VERIFIED.json"),Map.of("status","pass-complete-original-hops-rma-assessment-workflow","identical_cross_stage_bundle",true,"fresh_RData_verification",true,"original_fitting_repeated",false,"original_plotting_repeated",false,"producer_authenticated",false,"new_tool_credit",0));
    }
    private static void bindInvocation(Map<?,?> invocation,Map<?,?> report,Map<?,?> extraction,Map<?,?> assessment,Path extractionBundle)throws IOException {
        NextflowFiles.keys(invocation,"schema","producer_root","working_directory","options","mode");
        if(!"HOPS_RMA_ASSESSMENT_INVOCATION_V1".equals(invocation.get("schema"))||!"me_po_complete_declared_profile".equals(invocation.get("mode"))||!Objects.equals(report.get("producer_root"),invocation.get("producer_root")))throw new IOException("Workflow invocation identity differs");
        String producer=NextflowFiles.text(report.get("producer_root")),cwd=NextflowFiles.text(invocation.get("working_directory"));
        if(!Path.of(cwd).isAbsolute()||!Path.of(cwd).normalize().toString().equals(cwd)||!Path.of(producer).isAbsolute()||!Path.of(producer).normalize().toString().equals(producer))throw new IOException("Original workflow producer/working directory is noncanonical");
        var strings=new TreeMap<String,String>();for(var e:NextflowFiles.object(invocation.get("options")).entrySet())strings.put(NextflowFiles.text(e.getKey()),NextflowFiles.text(e.getValue()));
        var args=new ArrayList<String>();strings.forEach((k,v)->args.addAll(List.of(k,v)));var options=options(args.toArray(String[]::new));
        if(options.containsKey("--verify")||options.containsKey("--reader-runtime"))throw new IOException("A fitting invocation cannot be relabeled saved verification");
        for(String key:List.of("--maltextract-runtime","--post-runtime","--resources","--targets","--rma-list","--profile","--input-provenance","--emit-json","--out"))required(options,key);
        if(!"complete-def-anc".equals(options.get("--profile"))||!Objects.equals(options.get("--input-provenance"),report.get("input_provenance"))||!Objects.equals(options.get("--emit-json"),Objects.toString(assessment.get("emit_json"))))throw new IOException("Workflow invocation method/JSON declarations contradict stage reports");
        same(producer,resolveOriginal(cwd,options.get("--out")),"Workflow output declaration differs");
        same(producer+"/extraction",extraction.get("producer_root"),"Extraction producer differs from workflow stage");same(producer+"/assessment",assessment.get("producer_root"),"Assessment producer differs from workflow stage");
        same(resolveOriginal(cwd,options.get("--maltextract-runtime")),extraction.get("runtime_root"),"Original extraction provider declaration differs");same(resolveOriginal(cwd,options.get("--post-runtime")),assessment.get("provider_root"),"Original postprocessing provider declaration differs");
        var bindings=NextflowFiles.object(extraction.get("original_bindings"));String resources=resolveOriginal(cwd,options.get("--resources")),list=resolveOriginal(cwd,options.get("--rma-list"));
        same(resources+"/ncbi.map",bindings.get("inputs/resources/ncbi.map"),"Original name-map source declaration differs");same(resources+"/ncbi.tre",bindings.get("inputs/resources/ncbi.tre"),"Original taxonomy-tree source declaration differs");
        same(resolveOriginal(cwd,options.get("--targets")),bindings.get("inputs/targets.txt"),"Original target-file declaration differs");same(list,bindings.get("inputs/rma-list.tsv"),"Original complete RMA-list declaration differs");
        var rows=NextflowFiles.utf8(NextflowFiles.bytes(extractionBundle.resolve("inputs/rma-list.tsv"),16777216)).lines().toList();
        if(rows.size()<2||!rows.get(0).equals("sample_id\trma6"))throw new IOException("Complete original RMA-list header/population differs");
        for(String row:rows.subList(1,rows.size())) {String[] f=row.split("\t",-1);if(f.length!=2)throw new IOException("Incomplete captured RMA-list row");same(resolveOriginal(Path.of(list).getParent().toString(),f[1]),bindings.get("inputs/rma/"+f[0]+".rma6"),"Original complete RMA source declaration differs: "+f[0]);}
        var maltDefaults=Map.ofEntries(Map.entry("--maximum-file-bytes",1000000000L),Map.entry("--maximum-input-bytes",4000000000L),Map.entry("--maximum-reads",1000000L),Map.entry("--maximum-matches",10000000L),Map.entry("--maximum-samples",100L),Map.entry("--maximum-selected",10000L),Map.entry("--maximum-map-rows",10000000L),Map.entry("--maximum-map-characters",1000000000L),Map.entry("--maximum-tree-nodes",5000000L),Map.entry("--wall-seconds",600L),Map.entry("--heap-mib",4096L),Map.entry("--threads",2L),Map.entry("--gc-threads",1L));
        var maltFields=Map.ofEntries(Map.entry("--maximum-file-bytes","file_bytes"),Map.entry("--maximum-input-bytes","input_bytes"),Map.entry("--maximum-reads","reads"),Map.entry("--maximum-matches","matches"),Map.entry("--maximum-samples","samples"),Map.entry("--maximum-selected","selected"),Map.entry("--maximum-map-rows","map_rows"),Map.entry("--maximum-map-characters","map_characters"),Map.entry("--maximum-tree-nodes","tree_nodes"),Map.entry("--wall-seconds","wall_seconds"),Map.entry("--heap-mib","heap_mib"),Map.entry("--threads","threads"),Map.entry("--gc-threads","gc_threads"));
        capacities(options,NextflowFiles.object(extraction.get("capacities")),maltDefaults,maltFields,"extraction");
        var postDefaults=Map.of("--maximum-file-bytes",1000000000L,"--maximum-bundle-bytes",8000000000L,"--maximum-files",100000L,"--maximum-table-rows",1000000L,"--maximum-table-cells",100000000L,"--maximum-samples",100L,"--maximum-taxa",10000L,"--threads",2L,"--wall-seconds",600L);
        var postFields=Map.of("--maximum-file-bytes","file_bytes","--maximum-bundle-bytes","bundle_bytes","--maximum-files","files","--maximum-table-rows","rows","--maximum-table-cells","cells","--maximum-samples","samples","--maximum-taxa","taxa","--threads","threads","--wall-seconds","wall_seconds");capacities(options,NextflowFiles.object(assessment.get("capacities")),postDefaults,postFields,"assessment");
    }
    private static void capacities(Map<String,String> options,Map<?,?> saved,Map<String,Long> defaults,Map<String,String> fields,String stage)throws IOException {
        for(var e:defaults.entrySet()) {String raw=options.getOrDefault(e.getKey(),e.getValue().toString());if(!raw.matches("[1-9][0-9]*"))throw new IOException("Original resource declaration is inexact: "+e.getKey());long expected;try{expected=Long.parseLong(raw);}catch(NumberFormatException failure){throw new IOException("Original resource declaration overflows",failure);}if(NextflowFiles.integer(saved.get(fields.get(e.getKey())),1,Long.MAX_VALUE)!=expected)throw new IOException("Workflow "+stage+" resource declaration differs: "+e.getKey());}
    }
    private static String resolveOriginal(String directory,String text)throws IOException {if(text==null||text.isEmpty())throw new IOException("Missing original source/provider path");Path p=Path.of(text);return (p.isAbsolute()?p:Path.of(directory).resolve(p)).normalize().toString();}
    private static int extract(List<String> args,Path stdout,Path stderr)throws IOException {try(var so=stream(stdout);var se=stream(stderr)){return MaltExtractWorkflowCli.run(args.toArray(String[]::new),so,se);}}
    private static int post(List<String> args,Path stdout,Path stderr)throws IOException {try(var so=stream(stdout);var se=stream(stderr)){return HopsPostprocessingCli.run(args.toArray(String[]::new),so,se);}}
    private static PrintStream stream(Path path)throws IOException{return new PrintStream(Files.newOutputStream(path,StandardOpenOption.CREATE_NEW),false,StandardCharsets.UTF_8);}
    private static void requireStage(int code,String stage,Path diagnostic)throws IOException {if(code==3)throw new Skipped(stage+" unavailable; inspect "+diagnostic);if(code!=0)throw new IOException(stage+" failed; inspect "+diagnostic);}
    private static Map<String,NextflowFiles.Pin> inventory(Path root,String omitted)throws IOException {NextflowFiles.directory(root);var map=new TreeMap<String,NextflowFiles.Pin>();long total=0;try(var paths=Files.walk(root)){for(Path p:paths.filter(p->!Files.isDirectory(p,LinkOption.NOFOLLOW_LINKS)).toList()){String name=NextflowFiles.member(root.relativize(p).toString().replace('\\','/'));if(name.equals(omitted))continue;if(map.size()>=FILES)throw new IOException("Complete workflow file capacity exceeded");var pin=NextflowFiles.pin(p,FILE_BYTES,()->{});total=Math.addExact(total,pin.bytes());if(total>TOTAL_BYTES)throw new IOException("Complete workflow byte capacity exceeded");map.put(name,pin);}}return map;}
    private static Map<String,NextflowFiles.Pin> pins(Object value)throws IOException {var pins=new TreeMap<String,NextflowFiles.Pin>();for(var e:NextflowFiles.object(value).entrySet())pins.put(NextflowFiles.member(NextflowFiles.text(e.getKey())),NextflowFiles.fingerprint(e.getValue(),FILE_BYTES));return pins;}
    private static void same(Object a,Object b,String cause)throws IOException {if(!NextflowJson.json(a).equals(NextflowJson.json(b)))throw new IOException(cause);}
    private static void disjoint(Path output,List<Path> inputs)throws IOException {for(Path p:inputs)if(output.startsWith(p)||p.startsWith(output))throw new IOException("Owned output and input/provider may not overlap");}
    private static Path path(String value)throws IOException {Path p=Path.of(value).toAbsolutePath().normalize(),existing=Files.exists(p,LinkOption.NOFOLLOW_LINKS)?p:p.getParent();if(existing==null||!existing.toRealPath().equals(existing))throw new IOException("Canonical existing path/parent required: "+p);return p;}
    private static String required(Map<String,String> options,String key)throws IOException {String value=options.get(key);if(value==null||value.isEmpty())throw new IOException("Missing explicit option: "+key);return value;}
    private static Map<String,String> options(String[] args)throws IOException {var allowed=new HashSet<>(EXTRACT);allowed.addAll(POST);allowed.addAll(Set.of("--verify","--reader-runtime","--maltextract-runtime","--post-runtime","--out","--emit-json"));var map=new TreeMap<String,String>();for(int i=0;i<args.length;i+=2)if(i+1>=args.length||!allowed.contains(args[i])||map.putIfAbsent(args[i],args[i+1])!=null)throw new IOException("Require complete unique known options; see --help");return map;}
    private static String warnings(){return "# HOPS RMA ASSESSMENT WARNINGS AND REQUIRED ACTIONS\n\n**This declared complete-def-anc workflow disables original sampling, destacking and duplicate removal. It is a method choice, not recovered author settings. Whole HOPS/MALT/index/alignment and biological reproduction are not admitted.**\n\nThe assessment consumes the complete byte-identical extraction bundle, including every captured RMA and resource. Every stage's original outputs/process records and failure markers are retained. Source classes are screening criteria; missing/insufficient evidence remains unassessable, never absence. Review extraction/bundle/WARNINGS.md, assessment/bundle/WARNINGS.md, both stage stderr logs and original candidate profiles manually. Intermediate extraction can remain independently usable after a later stage fails; the failed workflow itself has no admitted final result. Saved verification checks both complete stages, their exact handoff and fresh RData fields; no original fitting/plotting is repeated, and producer authenticity is not established.\n\n"+ACTION+"\n";}
    private static String help(){return "--maltextract-runtime FULL_17_JAVA8_PROVIDER --post-runtime PUBLIC_R405_PROVIDER --resources COMPLETE_NCBI_RESOURCES --targets LITERAL_TARGET_FILE --rma-list COMPLETE_SAMPLE_TSV --profile complete-def-anc --input-provenance supplied|native-accession-alternative --emit-json true|false --out NEW_NATIVE_LINUX_DIRECTORY\n--verify COMPLETE_WORKFLOW --reader-runtime EXACT_17_READER --post-runtime PUBLIC_R405_PROVIDER --out NEW_NATIVE_LINUX_VERIFICATION\nExtraction capacity/resource options retain their MaltExtractWorkflowCli names. Postprocessing options: --maximum-table-rows, --maximum-table-cells, --maximum-taxa, --maximum-bundle-bytes, --maximum-files. Shared --maximum-file-bytes, --maximum-samples, --threads and --wall-seconds are passed explicitly to both stages. Complete read and mapping populations are never truncated.\n"+ACTION;}
}
